/*!
 * wega-music-boss.js - OMNIWEGA boss fight add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "boss" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("boss") works.
 * Track: Mario & Luigi boss battle - supplied by the player.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-boss] load wega-music.js first"); return; }
  D.boss = {
    title: "Boss Battle (OMNIWEGA Theme)",
    credit: "Mario & Luigi boss battle",
    duration: 125.31,
    loopStart: 0.05,
    loopEnd: 123.7,
    gain: 0.9,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("boss") < 0) W.tracks.push("boss");
})(typeof window !== "undefined" ? window : globalThis);
